// Create a custom ingredient serializer
public class MyIngredientSerializer implements IIngredientSerializer<MyIngredient> {
    public static final MyIngredientSerializer INSTANCE = new MyIngredientSerializer();

    @Override
    public MyIngredient parse(JsonContext context, JsonObject json) {
        String type = JSONUtils.getAsString(json, "type");
        return new MyIngredient(type);
    }

    @Override
    public JsonObject serialize(JsonContext context, MyIngredient ingredient) {
        JsonObject json = new JsonObject();
        json.addProperty("type", ingredient.getType());
        return json;
    }
}

